contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single entrypoint carrying out the property check
    // params: unlock time for Put, amount to send with Put, amount to attempt to Collect
    function run(uint unlockTime, uint putAmount, uint collectAmount) public payable {
        // ensure this contract can fund the Put call
        require(address(this).balance >= putAmount, "insufficient test balance for Put");

        // read initial observable values
        uint beforeHolderBalance = c.Acc(address(this)).balance;
        uint beforeContractBalance = address(c).balance;

        // perform Put sending Ether to c
        c.Put{value: putAmount}(unlockTime);

        // read after Put
        uint afterPutHolderBalance = c.Acc(address(this)).balance;
        uint afterPutContractBalance = address(c).balance;

        // Attempt Collect and observe whether it reverts
        bool collectReverted;
        try c.Collect(collectAmount) {
            collectReverted = false;
        } catch {
            collectReverted = true;
        }

        // read final observable values
        uint finalHolderBalance = c.Acc(address(this)).balance;
        uint finalContractBalance = address(c).balance;

        // General property:
        // If Collect did not revert, then the holder's recorded balance decreased by exactly collectAmount
        // relative to afterPutHolderBalance, and the contract's balance decreased by at least collectAmount
        // (it may decrease more if other side-effects occurred), and if Collect reverted, balances remain unchanged
        assert(
            (
                !collectReverted && finalHolderBalance + collectAmount == afterPutHolderBalance && afterPutContractBalance >= finalContractBalance + collectAmount
            ) || (
                collectReverted && finalHolderBalance == afterPutHolderBalance && finalContractBalance == afterPutContractBalance
            )
        );
    }

    // allow receiving Ether so the test can be funded externally
    receive() external payable {}
}

