contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single entrypoint: perform a Put (optionally) and then attempt Collect(amount).
    // Params:
    //  putAmount: Ether to send with Put (can be 0)
    //  unlockTime: parameter for Put
    //  collectAmount: amount to pass to Collect
    function run(uint unlockTime, uint putAmount, uint collectAmount) public payable {
        // ensure this test contract can fund the Put call
        require(address(this).balance >= putAmount, "insufficient balance for Put");

        // Observe recorded balance for this contract's address before any interactions
        (uint beforeUnlock, uint beforeBalance) = c.Acc(address(this));

        // Perform Put (may be zero value)
        c.Put{value: putAmount}(unlockTime);

        // Observe recorded balance immediately after Put
        (uint afterPutUnlock, uint afterPutBalance) = c.Acc(address(this));

        // Try to Collect collectAmount and record whether it reverted
        bool collectReverted;
        try c.Collect(collectAmount) {
            collectReverted = false;
        } catch {
            collectReverted = true;
        }

        // Observe recorded balance after the Collect attempt
        (uint finalUnlock, uint finalBalance) = c.Acc(address(this));

        // General property (single assert):
        // If Collect succeeded then finalBalance + collectAmount == afterPutBalance.
        // If Collect reverted then finalBalance == afterPutBalance.
        // This states the observable effect on the holder balance is either a successful subtraction of collectAmount or no change.
        assert((!collectReverted && finalBalance + collectAmount == afterPutBalance) || (collectReverted && finalBalance == afterPutBalance));
    }

    // allow receiving Ether so the test can be funded externally
    receive() external payable {}
}

