contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Params:
    //  unlockTime: passed to Put
    //  putAmount: ether sent with Put
    //  collectAmount: amount attempted to Collect
    function run(uint unlockTime, uint putAmount, uint collectAmount) public payable {
        // ensure this test contract can fund the Put call
        require(address(this).balance >= putAmount, "insufficient balance for Put");

        // read holder balance before any calls (should be 0 for fresh deploy but read anyway)
        uint beforeAcc = c.Acc(address(this)).balance;

        // perform Put to add funds and set unlockTime
        c.Put{value: putAmount}(unlockTime);

        // read balance after Put and before Collect
        uint afterPutAcc = c.Acc(address(this)).balance;

        // attempt Collect and record whether it reverted
        bool collectReverted;
        try c.Collect(collectAmount) {
            collectReverted = false;
        } catch {
            collectReverted = true;
        }

        // read balance after Collect attempt
        uint finalAcc = c.Acc(address(this)).balance;

        // If Collect succeeded then finalAcc == afterPutAcc - collectAmount.
        // If Collect reverted then finalAcc == afterPutAcc.
        // Use safe comparisons without underflow in the assert by branching on collectReverted.
        assert((!collectReverted && afterPutAcc >= collectAmount && finalAcc == (afterPutAcc - collectAmount)) || (collectReverted && finalAcc == afterPutAcc));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will test behavior of Put and Collect for msg.sender == address(this) (InvMutTest contract)
    // Inputs: amountToPut to deposit via Put (sent as Ether), unlockOffset to set unlockTime relative to now,
    // and amountToCollect to attempt to collect. run is payable so it can receive Ether from the caller
    // of the test harness; we will require this contract has enough balance to forward amountToPut.
    function run(uint amountToPut, uint unlockOffset, uint amountToCollect) public payable {
        require(address(this).balance >= amountToPut, "insufficient funds to fund Put");

        // Read initial observable values
        uint beforeRecorded = c.Acc(address(this)).balance; // public getter for mapping
        uint beforeContractBal = address(c).balance;

        // Call Put to deposit amountToPut and set unlockTime = block.timestamp + unlockOffset (if offset>0) or now
        // Note: Put signature: Put(uint _unlockTime) public nonReentrant_ payable
        uint desiredUnlock = block.timestamp + unlockOffset;
        c.Put{value: amountToPut}(desiredUnlock);

        // Read after-put values
        uint afterPutRecorded = c.Acc(address(this)).balance;
        uint afterPutContractBal = address(c).balance;

        // Sanity: recorded increased by amountToPut and contract balance increased by amountToPut
        // (these are used later; we don't assert them separately to keep single final assert)

        // Attempt Collect for amountToCollect, capturing whether it reverted
        bool reverted;
        try c.Collect{value: 0}(amountToCollect) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read final observed values
        uint finalRecorded = c.Acc(address(this)).balance;
        uint finalContractBal = address(c).balance;

        // The property: if Collect succeeded (not reverted) then recorded balance decreased by amountToCollect
        // and contract balance decreased by amountToCollect; if Collect reverted then both remain equal to afterPut values.
        assert(
            (!reverted && finalRecorded + amountToCollect == afterPutRecorded && finalContractBal + amountToCollect == afterPutContractBal)
            || (reverted && finalRecorded == afterPutRecorded && finalContractBal == afterPutContractBal)
        );
    }

    receive() external payable {}
}

